import java.util.*;

class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> words = new HashSet<>(wordDict);
        Map<Integer, List<String>> memo = new HashMap<>();
        return sentencesFrom(s, 0, words, memo);
    }

    private List<String> sentencesFrom(String s, int start, Set<String> words,
            Map<Integer, List<String>> memo) {
        if (memo.containsKey(start)) return memo.get(start);
        List<String> result = new ArrayList<>();
        if (start == s.length()) {
            result.add("");
            memo.put(start, result);
            return result;
        }
        for (int end = start + 1; end <= s.length(); end++) {
            String word = s.substring(start, end);
            if (!words.contains(word)) continue;
            for (String suffix : sentencesFrom(s, end, words, memo)) {
                result.add(suffix.isEmpty() ? word : word + " " + suffix);
            }
        }
        memo.put(start, result);
        return result;
    }
}

import java.util.*;

class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> words = new HashSet<>(wordDict);
        int n = s.length();
        int maxWordLength = 0;
        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
        boolean[] canFinish = new boolean[n + 1];
        canFinish[n] = true;
        for (int start = n - 1; start >= 0; start--) {
            int limit = Math.min(n, start + maxWordLength);
            for (int end = start + 1; end <= limit; end++) {
                if (canFinish[end] && words.contains(s.substring(start, end))) {
                    canFinish[start] = true;
                    break;
                }
            }
        }
        List<String> answer = new ArrayList<>();
        if (!canFinish[0]) return answer;
        backtrack(s, 0, maxWordLength, words, canFinish, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(String s, int start, int maxWordLength, Set<String> words,
            boolean[] canFinish, List<String> path, List<String> answer) {
        if (start == s.length()) {
            answer.add(String.join(" ", path));
            return;
        }
        int limit = Math.min(s.length(), start + maxWordLength);
        for (int end = start + 1; end <= limit; end++) {
            if (!canFinish[end]) continue;
            String word = s.substring(start, end);
            if (!words.contains(word)) continue;
            path.add(word);
            backtrack(s, end, maxWordLength, words, canFinish, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> words = new HashSet<>(wordDict);
        int n = s.length();
        int maxWordLength = 0;
        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
        List<List<String>> dp = new ArrayList<>();
        for (int i = 0; i <= n; i++) dp.add(new ArrayList<>());
        dp.get(0).add("");
        for (int end = 1; end <= n; end++) {
            int firstStart = Math.max(0, end - maxWordLength);
            for (int start = firstStart; start < end; start++) {
                if (dp.get(start).isEmpty()) continue;
                String word = s.substring(start, end);
                if (!words.contains(word)) continue;
                for (String prefix : dp.get(start)) {
                    dp.get(end).add(prefix.isEmpty() ? word : prefix + " " + word);
                }
            }
        }
        return dp.get(n);
    }
}

import java.util.*;

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
    }

    public List<String> wordBreak(String s, List<String> wordDict) {
        TrieNode root = new TrieNode();
        for (String word : wordDict) insert(root, word);
        Map<Integer, List<String>> memo = new HashMap<>();
        return dfs(s, 0, root, memo);
    }

    private void insert(TrieNode root, String word) {
        TrieNode node = root;
        for (char ch : word.toCharArray()) {
            int idx = ch - 'a';
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.word = word;
    }

    private List<String> dfs(String s, int start, TrieNode root, Map<Integer, List<String>> memo) {
        if (memo.containsKey(start)) return memo.get(start);
        List<String> result = new ArrayList<>();
        if (start == s.length()) {
            result.add("");
            memo.put(start, result);
            return result;
        }
        TrieNode node = root;
        for (int end = start; end < s.length(); end++) {
            node = node.children[s.charAt(end) - 'a'];
            if (node == null) break;
            if (node.word == null) continue;
            for (String suffix : dfs(s, end + 1, root, memo)) {
                result.add(suffix.isEmpty() ? node.word : node.word + " " + suffix);
            }
        }
        memo.put(start, result);
        return result;
    }
}

import java.util.*;

class Solution {
    static class Edge {
        int next;
        String word;
        Edge(int next, String word) {
            this.next = next;
            this.word = word;
        }
    }

    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> words = new HashSet<>(wordDict);
        int n = s.length();
        int maxWordLength = 0;
        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
        boolean[] canFinish = new boolean[n + 1];
        canFinish[n] = true;
        for (int start = n - 1; start >= 0; start--) {
            int limit = Math.min(n, start + maxWordLength);
            for (int end = start + 1; end <= limit; end++) {
                String word = s.substring(start, end);
                if (canFinish[end] && words.contains(word)) {
                    graph.get(start).add(new Edge(end, word));
                    canFinish[start] = true;
                }
            }
        }
        List<String> answer = new ArrayList<>();
        if (!canFinish[0]) return answer;
        enumerate(graph, 0, n, new ArrayList<>(), answer);
        return answer;
    }

    private void enumerate(List<List<Edge>> graph, int index, int target,
            List<String> path, List<String> answer) {
        if (index == target) {
            answer.add(String.join(" ", path));
            return;
        }
        for (Edge edge : graph.get(index)) {
            path.add(edge.word);
            enumerate(graph, edge.next, target, path, answer);
            path.remove(path.size() - 1);
        }
    }
}
